# How many labels of each type each cluster holds.
counts = input_0.groupby(["cluster", "label_type"]).size()

return counts.reset_index(name="labels")

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "How many labels of each type each cluster holds.",
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "cluster",
      "type": "ordinal",
      "title": "Cluster",
      "axis": {
        "labelAngle": 0
      }
    },
    "y": {
      "field": "labels",
      "type": "quantitative",
      "aggregate": "sum",
      "title": "Labels"
    },
    "color": {
      "field": "label_type",
      "type": "nominal",
      "title": "Label type"
    },
    "tooltip": [
      {
        "field": "cluster"
      },
      {
        "field": "label_type"
      },
      {
        "field": "labels"
      }
    ]
  }
}
